using namespace std;
int n,v[10001];
int Imparte (int st,int dr)
{ int i,j,ii,jj,aux;
 i=st;
 j=dr;
 ii=0;
 jj=-1;
 while(i<j)
 {
 if(v[i]>v[j])
 {
 aux=v[i];
 v[i]=v[j];
 v[j]=aux;
 aux=ii;
 ii=-jj;
 jj=-aux;
 }
 i=i+ii;
 j=j+jj;
 }
 return i;
}
void Quick(int st, int dr)
{
 int p;
 if(st<dr)
 {
 p=Imparte(st,dr);
 Quick(st,p-1);
 Quick(p+1,dr);
 }
}
int main()
{
 int i;
 ifstream f("QUICK.IN");
 ofstream g("QUICK.OUT");
 f>>n;
 for(i=1;i<=n;i++)
 f>>v[i];
 Quick(1,n);
 for(i=1;i<=n;i++)
 g<<v[i]<<" ";
 return 0;
}

#include <iostream>
using namespace std;
int A[100],n;

void Pozitioneaza (int start, int finis,int &k)
{int i, j, d,aux;
d=0; i=start; j=finis;
while (i<j)
{if (A[i]>A[j])
{ aux=A[i];A[i]=A[j]; A[j]=aux; d=1-d ;
 }
 i+=d; j-=1-d;
}
k= i;
}

void Quick (int inceput, int sfarsit)
{ int k;
if (inceput < sfarsit)
{
Pozitioneaza (inceput, sfarsit, k);
Quick (inceput, k-1);
Quick (k+1, sfarsit);
}
}
